using System; using System.Collections.Generic; using UnityEngine;
namespace VampPon.UnitySpike.Runtime.Gameplay.Definitions { [CreateAssetMenu(menuName="YorunoShirube/U47/Stage1 Registry")] public sealed class Stage1GameplayDataRegistry : ScriptableObject { [SerializeField] private int schemaVersion; [SerializeField] private string sourceHash,exportHash; [SerializeField] private CharacterGameplayDefinition character; [SerializeField] private int weaponSlots=5,passiveSlots=5,rareItemSlots=2; [SerializeField] private WeaponDefinition[] weapons; [SerializeField] private PassiveDefinition[] passives; [SerializeField] private RareItemDefinition[] rareItems; [SerializeField] private EvolutionDefinition[] evolutions; private Dictionary<string,WeaponDefinition> weaponLookup; private Dictionary<string,PassiveDefinition> passiveLookup; private Dictionary<string,RareItemDefinition> rareLookup; private Dictionary<string,EvolutionDefinition> evolutionLookup; public int SchemaVersion=>schemaVersion; public string SourceHash=>sourceHash; public string ExportHash=>exportHash; public CharacterGameplayDefinition Character=>character; public int WeaponSlots=>weaponSlots; public int PassiveSlots=>passiveSlots; public int RareItemSlots=>rareItemSlots; public IReadOnlyList<WeaponDefinition> Weapons=>weapons; public IReadOnlyList<PassiveDefinition> Passives=>passives; public IReadOnlyList<RareItemDefinition> RareItems=>rareItems; public IReadOnlyList<EvolutionDefinition> Evolutions=>evolutions; public void SetData(int schema,string source,string export,CharacterGameplayDefinition characterValue,int weaponLimit,int passiveLimit,int rareLimit,WeaponDefinition[] weaponValues,PassiveDefinition[] passiveValues,RareItemDefinition[] rareValues,EvolutionDefinition[] evolutionValues){schemaVersion=schema;sourceHash=source;exportHash=export;character=characterValue;weaponSlots=weaponLimit;passiveSlots=passiveLimit;rareItemSlots=rareLimit;weapons=weaponValues;passives=passiveValues;rareItems=rareValues;evolutions=evolutionValues;BuildLookups();} public void BuildLookups(){weaponLookup=Build(weapons);passiveLookup=Build(passives);rareLookup=Build(rareItems);evolutionLookup=Build(evolutions);} private void OnEnable()=>BuildLookups(); private static Dictionary<string,T> Build<T>(IEnumerable<T> values) where T:GameDefinition{var result=new Dictionary<string,T>(StringComparer.Ordinal);if(values!=null)foreach(var value in values)if(value!=null&&!result.TryAdd(value.Id,value))throw new InvalidOperationException($"Duplicate gameplay ID: {value.Id}");return result;} public WeaponDefinition GetWeapon(string id)=>Lookup(weaponLookup,id,"weapon"); public PassiveDefinition GetPassive(string id)=>Lookup(passiveLookup,id,"passive"); public RareItemDefinition GetRareItem(string id)=>Lookup(rareLookup,id,"rare item"); public EvolutionDefinition GetEvolution(string id)=>Lookup(evolutionLookup,id,"evolution"); private static T Lookup<T>(Dictionary<string,T> lookup,string id,string kind){if(lookup!=null&&lookup.TryGetValue(id,out var value))return value;throw new KeyNotFoundException($"Missing {kind} definition: {id}");} } }
